To solve the problem, we'll create a mathematical model using Gurobipy to find the minimum cost transportation policy. The model will include variables for each warehouse-port pair, an objective function to minimize total transportation cost, and constraints to ensure supply and demand are met.

```python
import gurobipy as gp
from gurobipy import GRB

# Data
warehouses = ['Verona', 'Perugia', 'Rome', 'Pescara', 'Taranto', 'Lamezia']
ports = ['Genoa', 'Venice', 'Ancona', 'Naples', 'Bari']

inventory = {'Verona': 10, 'Perugia': 12, 'Rome': 20, 
             'Pescara': 24, 'Taranto': 18, 'Lamezia': 40}
demand = {'Genoa': 20, 'Venice': 15, 'Ancona': 25, 
          'Naples': 33, 'Bari': 21}

distances = {
    'Verona': {'Genoa': 290, 'Venice': 115, 'Ancona': 355, 'Naples': 715, 'Bari': 810},
    'Perugia': {'Genoa': 380, 'Venice': 340, 'Ancona': 165, 'Naples': 380, 'Bari': 610},
    'Rome': {'Genoa': 505, 'Venice': 530, 'Ancona': 285, 'Naples': 220, 'Bari': 450},
    'Pescara': {'Genoa': 655, 'Venice': 450, 'Ancona': 155, 'Naples': 240, 'Bari': 315},
    'Taranto': {'Genoa': 1010, 'Venice': 840, 'Ancona': 550, 'Naples': 305, 'Bari': 95},
    'Lamezia': {'Genoa': 1072, 'Venice': 1097, 'Ancona': 747, 'Naples': 372, 'Bari': 333}
}

# Create model
env = gp.Env()
model = gp.Model(env=env)

# Variables
var_dict = {}
for w in warehouses:
    for p in ports:
        var_dict[(w, p)] = model.addVar(vtype=GRB.INTEGER, name=f"x_{w}_{p}")

# Objective function
obj = 0
for w in warehouses:
    for p in ports:
        d = distances[w][p]
        obj += 30 * d * var_dict[(w, p)]
model.setObjective(obj, GRB.MINIMIZE)

# Supply constraints
for w in warehouses:
    total_supply = sum(var_dict[(w, p)] for p in ports)
    model.addConstr(total_supply <= inventory[w], name=f"Supply_{w}")

# Demand constraints
for p in ports:
    total_demand = sum(var_dict[(w, p)] for w in warehouses)
    model.addConstr(total_demand >= demand[p], name=f"Demand_{p}")

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
    for w in warehouses:
        for p in ports:
            print(f"x_{w}_{p} = {var_dict[(w, p)].x}")
else:
    print("No optimal solution found.")
```

