import gurobipy as gp
from gurobipy import GRB

env = gp.Env()
model = gp.Model(env=env)

N = [1, 2, 3]
T = list(range(1, 23))

D = {1: 5300, 2: 4500, 3: 5400}
P = {1: 124, 2: 109, 3: 115}
C = {1: 73.3, 2: 52.9, 3: 65.4}
F = {1: 170000, 2: 150000, 3: 100000}
Q = {1: 500, 2: 450, 3: 550}
MB = {1: 20, 2: 20, 3: 16}

y = {}
x = {}

for n in N:
    y[n] = model.addVar(vtype=GRB.BINARY)
    x_n = []
    for t in T:
        var = model.addVar(lb=0)
        x_n.append(var)
    x[n] = x_n

obj = 0
for n in N:
    sum_xn = sum(x[n])
    profit_per_100kg = P[n] - C[n]
    obj += profit_per_100kg * sum_xn - F[n] * y[n]

model.setObjective(obj, GRB.MAXIMIZE)

for n in N:
    for t in T:
        model.addConstr(x[n][t-1] <= Q[n] * y[n])

for n in N:
    sum_xn = sum(x[n])
    model.addConstr(sum_xn <= D[n])

for n in N:
    sum_xn = sum(x[n])
    model.addConstr(sum_xn >= MB[n] * y[n])

model.optimize()

if model.status == GRB.OPTIMAL:
    total_revenue = model.objVal
    print(f"FINAL_OBJECTIVE={total_revenue}")

import gurobipy as gp
from gurobipy import GRB

# Read environment from Gurobi
env = gp.Env()

# Create model
model = gp.Model(env=env)

# Define variables for each shift (i=1 to 6)
x = {}
for i in range(1, 7):
    x[i] = model.addVar(vtype=GRB.INTEGER, lb=0)

# Requirements for each time period j=1 to 6
d = {1: 10, 2: 15, 3: 25, 4: 20, 5: 18, 6: 12}

# Objective function: minimize total number of salespeople
model.setObjective(gp.quicksum(x[i] for i in range(1, 7)), GRB.MINIMIZE)

# Constraints for each time period j
for j in range(1, 7):
    if j == 1:
        shifts = [1, 6]
    elif j == 2:
        shifts = [1, 2]
    elif j == 3:
        shifts = [2, 3]
    elif j == 4:
        shifts = [3, 4]
    elif j == 5:
        shifts = [4, 5]
    else:  # j == 6
        shifts = [5, 6]

    expr = gp.LinExpr()
    for s in shifts:
        expr.add(x[s])
    model.addConstr(expr >= d[j], f'constraint_{j}')

# Optimize the model
model.optimize()

# Check if solution is optimal and report the objective value
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")

