# Create a new model with the runtime-provided environment
env = None  # Replace with actual environment if provided
model = gp.Model(env=env)

# Define sets and indices
products = ['I', 'II', 'III']
A_machines = ['A1', 'A2']
B_machines = ['B1', 'B2', 'B3']

# Parameters
processing_times = {
    ('A1', 'I'): 5, ('A1', 'II'): 10,
    ('A2', 'I'): 7, ('A2', 'II'): 9, ('A2', 'III'): 12,
    ('B1', 'I'): 6, ('B1', 'II'): 8,
    ('B2', 'I'): 4, ('B2', 'III'): 11,
    ('B3', 'I'): 7
}

raw_material_cost = {'I': 0.25, 'II': 0.35, 'III': 0.50}
unit_price = {'I': 1.25, 'II': 2.00, 'III': 2.80}
effective_machine_hours = {
    'A1': 6000, 'A2': 10000,
    'B1': 4000, 'B2': 7000, 'B3': 4000
}
operating_cost = {
    'A1': 300, 'A2': 321,
    'B1': 250, 'B2': 783, 'B3': 200
}

# Calculate cost per hour for each machine
cost_per_hour_A = {j: operating_cost[j] / effective_machine_hours[j] for j in A_machines}
cost_per_hour_B = {k: operating_cost[k] / effective_machine_hours[k] for k in B_machines}

# Decision variables
x = model.addVars(products, A_machines, lb=0)
y = model.addVars(products, B_machines, lb=0)

# Objective function
model.setObjective(
    sum( (sum(x[i][j] for j in A_machines) * (unit_price[i] - raw_material_cost[i])) 
         for i in products ) 
    - sum( sum(t * cost_per_hour_A[j] for t, j in zip([processing_times[(j,i)] for i in products], [i for i in products])) 
           for j in A_machines )
    - sum( sum(t * cost_per_hour_B[k] for t, k in zip([processing_times[(k,i)] for i in products], [i for i in products])) 
           for k in B_machines ),
    GRB.MAXIMIZE
)

# Constraints
for j in A_machines:
    model.addConstr(
        sum( processing_times.get((j, i), 0) * x[i][j] for i in products ) <= effective_machine_hours[j]
    )

for k in B_machines:
    model.addConstr(
        sum( processing_times.get((k, i), 0) * y[i][k] for i in products ) <= effective_machine_hours[k]
    )

for i in products:
    model.addConstr(
        sum(x[i][j] for j in A_machines) == sum(y[i][k] for k in B_machines)
    )

# Optimize the model
model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found")
