import gurobipy as gp
from gurobipy import GRB

# Initialize environment and model
env = gp.Env()
model = gp.Model(env=env)

# Sets and indices
products = ['I', 'II', 'III']
machines_A = ['A1', 'A2']
machines_B = ['B1', 'B2', 'B3']

# Parameters
processing_times = {
    ('I', 'A1'): 5, ('II', 'A1'): 10,
    ('I', 'A2'): 7, ('II', 'A2'): 9, ('III', 'A2'): 12,
    ('I', 'B1'): 6, ('II', 'B1'): 8,
    ('III', 'B2'): 11
}
effective_hours = {
    'A1': 10000, 'A2': 4000,
    'B1': 7000, 'B2': 4000
}
equipment_cost = {
    'A1': 321, 'A2': 250,
    'B1': 783, 'B2': 200
}
raw_material_cost = {'I': 0.25, 'II': 0.35, 'III': 0.50}
unit_price = {'I': 1.25, 'II': 2.00, 'III': 2.80}

# Decision variables
x = {p: model.addVar(vtype=GRB.CONTINUOUS, lb=0) for p in products}
y = {m: model.addVar(vtype=GRB.BINARY) for m in machines_A + machines_B}

# Objective function
model.setObjective(
    sum((unit_price[p] - raw_material_cost[p]) * x[p] for p in products) -
    sum(equipment_cost[m] * y[m] for m in machines_A + machines_B),
    GRB.MAXIMIZE
)

# Constraints
for m in machines_A + machines_B:
    if m == 'B3':
        continue  # Skip B3 due to ambiguity
    lhs = gp.LinExpr()
    for p in products:
        t = processing_times.get((p, m), 0)
        if t > 0:
            lhs += x[p] * t
    rhs = effective_hours[m] * y[m]
    model.addConstr(lhs <= rhs)

# Binary constraints on machine usage
for m in machines_A + machines_B:
    model.addConstr(y[m] in {0, 1})

