        expr_weight = gp.LinExpr()
        for j in goods:
            expr_weight += x[(i,j)] * W[j]
        model.addConstr(expr_weight >= MinWeight * y[i], f"MinWeight_{i}")
        model.addConstr(expr_weight <= MaxWeight * y[i], f"MaxWeight_{i}")

