import gurobipy as gp
from gurobipy import GRB

def main():
    # Data
    I = [1, 2, 3, 4, 5, 6, 7]
    D = {
        1: {1:0, 2:86, 3:49, 4:57, 5:31, 6:69, 7:50},
        2: {1:86, 2:0, 3:68, 4:79, 5:93, 6:24, 7:5},
        3: {1:49, 2:68, 3:0, 4:16, 5:7, 6:72, 7:67},
        4: {1:57, 2:79, 3:16, 4:0, 5:90, 6:69, 7:1},
        5: {1:31, 2:93, 3:7, 4:90, 5:0, 6:86, 7:59},
        6: {1:69, 2:24, 3:72, 4:69, 5:86, 6:0, 7:81},
        7: {1:50, 2:5, 3:67, 4:1, 5:59, 6:81, 7:0}
    }

    # Create model
    env = gp.Env()
    model = gp.Model(env=env)

    # Variables
    x = {}
    for i in I:
        for j in I:
            if i != j:
                x[i, j] = model.addVar(vtype=GRB.BINARY)
    y = {j: model.addVar(vtype=GRB.BINARY) for j in I}
    w = {}
    for i in I:
        for j in I:
            if i != j:
                w[i, j] = model.addVar(vtype=GRB.BINARY)

    # Objective
    obj = gp.LinExpr()
    for i in I:
        for j in I:
            if i != j:
                obj += D[i][j] * x[i, j]
    model.setObjective(obj, GRB.MINIMIZE)

    # Constraints
    # Starting point constraint
    model.addConstr(y[1], GRB.EQUAL, 1)

    # Visit each city once (except starting city)
    for j in I:
        if j != 1:
            lhs_in = gp.LinExpr()
            for i in I:
                lhs_in += x[i, j]
            lhs_out = gp.LinExpr()
            for k in I:
                lhs_out += x[j, k]
            model.addConstr(lhs_in, GRB.EQUAL, lhs_out)

    # Subtour elimination constraints
    for i in I:
        for j in I:
            if i != j:
                model.addConstr(w[i, j] + y[j], GRB.GE, 1)

    # Binary variable constraints are handled by Gurobipy's default

    # Solve the model
    model.optimize()

    # Check if solution is optimal and feasible
    if model.status == GRB.Status.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal:.0f}")

        # Extract the route
        route = []
        current = 1
        visited = set()
        while True:
            route.append(current)
            visited.add(current)
            next_node = None
            for j in I:
                if x[current, j].x == 1 and j not in visited:
                    next_node = j
                    break
            if next_node is None:
                # Check if we can return to start
                if x[current][1].x == 1 and len(route) == len(I):
                    route.append(1)
                    break
                else:
                    break
            current = next_node

        print("Optimal visiting order:", route)
    else:
        print("No optimal solution found.")

