import gurobipy as gp
from gurobipy import GRB

def solve():
    # Create a new model with the provided environment
    env = gp.Env()
    model = gp.Model(env=env)

    # Define sets and indices
    coal_yards = ['A', 'B']
    residential_areas = [0, 1, 2]  # j=1,2,3 mapped to 0,1,2

    # Parameters
    S = {'A': 80, 'B': 100}
    D = [55, 75, 50]
    d = {
        ('A', 0): 10,
        ('A', 1): 5,
        ('A', 2): 6,
        ('B', 0): 4,
        ('B', 1): 8,
        ('B', 2): 15
    }

    # Decision variables
    X = {}
    for i in coal_yards:
        for j in residential_areas:
            X[i, j] = model.addVar(name=f'X_{i}_{j}', lowerBound=0)

    # Objective function
    obj = 0
    for i in coal_yards:
        for j in residential_areas:
            obj += d[(i, j)] * X[i, j]
    model.setObjective(obj, GRB.MINIMIZE)

    # Supply constraints
    for i in coal_yards:
        supply_sum = 0
        for j in residential_areas:
            supply_sum += X[i, j]
        model.addConstraint(supply_sum == S[i], f'Supply_{i}')

    # Demand constraints
    for j in residential_areas:
        demand_sum = X['A', j] + X['B', j]
        model.addConstraint(demand_sum == D[j], f'Demand_{j+1}')  # j=0 is area 1

    # Optimize the model
    model.optimize()

    if model.status == GRB.OPTIMAL:
        total_cost = obj.getValue()
        print(f'FINAL_OBJECTIVE={total_cost}')
    else:
        print("No optimal solution found")

if __name__ == "__main__":
    solve()

