from gurobipy import GRB

products = ['A1', 'A2', 'A3']
days = range(1, 23)

# Parameters
price = {'A1': 124, 'A2': 109, 'A3': 115}
production_cost = {'A1':73.30, 'A2':52.90, 'A3':65.40}
activation_cost = {'A1':170000, 'A2':150000, 'A3':100000}
max_demand = {'A1':5300, 'A2':4500, 'A3':5400}
production_quota = {'A1':500, 'A2':450, 'A3':550}
min_batch = {'A1':20, 'A2':20, 'A3':16}

model = gp.Model(env=env)

# Decision variables
y = {}
x = {}  # x[p][d]
for p in products:
    y[p] = model.addVar(vtype=GRB.BINARY, name=f'y_{p}')

    x[p] = {}
    for d in days:
        x[p][d] = model.addVar(lb=0, ub=production_quota[p], vtype=GRB.INTEGER, name=f'x_{p}_{d}')

# Constraints
for p in products:
    # Constraint 1: Daily production quota
    for d in days:
        model.addConstr(x[p][d] <= production_quota[p], f'daily_quota_{p}_{d}')

    # Constraint 4: Minimum batch size
    expr = gp.quicksum(x[p][d] for d in days)
    model.addConstr(expr >= min_batch[p] * y[p], f'minimum_batch_{p}')

# Global constraints
for p in products:
    # Constraint 3: Maximum demand
    expr = gp.quicksum(x[p][d] for d in days)
    model.addConstr(expr <= max_demand[p], f'maximum_demand_{p}')

# Objective function
profit = 0
for p in products:
    for d in days:
        profit += (price[p] - production_cost[p]) * x[p][d]

costs = 0
for p in products:
    costs += activation_cost[p] * y[p]

model.setObjective(profit - costs, GRB.MAXIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
